//! Symbol tables for libraries that are loaded while the program runs.
//!
//! X11, EGL, ALSA and XInput may be absent from a player's machine. We do not
//! link them. `nadir-platform` opens each one with `dlopen` or
//! `LoadLibraryW`, and a table generated by the `dynlib!` macro looks up
//! every function we call in it. A library that lacks some of them gives one
//! error that names them all, in place of a loader failure before `main`.
//!
//! This crate declares the tables. It does not open libraries: a table sees
//! one through the [`Library`] trait, which `nadir-platform` implements.

use core::ffi::{CStr, c_void};
use std::fmt;

/// A loaded library, as a symbol table sees it.
pub trait Library {
    /// Returns the address of the symbol called `name`, or null if the
    /// library has no such symbol.
    fn symbol(&self, name: &CStr) -> *const c_void;
}

/// The symbols that a table declares and a library does not have.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MissingSymbols {
    /// The name of every missing symbol, in the order the table declares
    /// them. Never empty.
    pub names: Vec<&'static str>,
}

impl fmt::Display for MissingSymbols {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let noun = if self.names.len() == 1 {
            "symbol"
        } else {
            "symbols"
        };
        write!(f, "missing {noun}: {}", self.names.join(", "))
    }
}

impl std::error::Error for MissingSymbols {}

/// Declares a table of functions that are looked up in a loaded library.
///
/// ```text
/// dynlib! {
///     /// The functions we call in `libexample.so.1`.
///     pub struct Example: extern "C" {
///         /// Adds two numbers. `example.h`: `int example_add(int a, int b)`.
///         fn example_add(a: c_int, b: c_int) -> c_int;
///     }
/// }
/// ```
///
/// This expands to a struct with one public field for each function. The
/// field has the function's C name and is an `unsafe extern` function pointer
/// with the calling convention given. The struct also gets
/// `unsafe fn load(&dyn Library) -> Result<Self, MissingSymbols>`.
//
// Only Linux has tables so far. An unused macro is a warning, which CI treats
// as an error, so the macro exists only where something uses it. Name each
// other system here, and on the `use` below, when it gets its first table.
#[cfg(any(target_os = "linux", test))]
macro_rules! dynlib {
    (
        $(#[$table_attr:meta])*
        $vis:vis struct $table:ident: extern $abi:literal {
            $(
                $(#[$symbol_attr:meta])*
                fn $symbol:ident($($arg:ident: $arg_ty:ty),* $(,)?) $(-> $ret:ty)?;
            )+
        }
    ) => {
        $(#[$table_attr])*
        // The fields keep the C names of the functions, so that each one can
        // be compared with its header.
        #[allow(non_snake_case)]
        $vis struct $table {
            $(
                $(#[$symbol_attr])*
                pub $symbol: unsafe extern $abi fn($($arg: $arg_ty),*) $(-> $ret)?,
            )+
        }

        impl $table {
            /// Looks up every function of the table in `library`.
            ///
            /// # Errors
            ///
            /// If the library lacks any of them, the error names every
            /// missing one, not only the first.
            ///
            /// # Safety
            ///
            /// - Each symbol that `library` finds must be the function this
            ///   table declares under that name, with the same parameters,
            ///   return type and calling convention. That is, `library` must
            ///   be the library the table was written for.
            /// - The library must stay loaded for as long as any function
            ///   pointer in the returned table can be called.
            // The local variables have the C names too.
            #[allow(non_snake_case)]
            $vis unsafe fn load(
                library: &dyn $crate::dynlib::Library,
            ) -> ::core::result::Result<Self, $crate::dynlib::MissingSymbols> {
                let mut missing = ::std::vec::Vec::new();
                $(
                    let $symbol = library.symbol(const {
                        match ::core::ffi::CStr::from_bytes_with_nul(
                            concat!(stringify!($symbol), "\0").as_bytes(),
                        ) {
                            Ok(name) => name,
                            Err(_) => panic!("an identifier has no NUL in it"),
                        }
                    });
                    if $symbol.is_null() {
                        missing.push(stringify!($symbol));
                    }
                )+
                if !missing.is_empty() {
                    return Err($crate::dynlib::MissingSymbols { names: missing });
                }
                Ok(Self {
                    $(
                        // SAFETY: the address is not null, which was checked
                        // above, and the caller promises that it is a
                        // function of this type. A data pointer and a
                        // function pointer have the same size on every
                        // target we support.
                        $symbol: unsafe {
                            ::core::mem::transmute::<
                                *const ::core::ffi::c_void,
                                unsafe extern $abi fn($($arg_ty),*) $(-> $ret)?,
                            >($symbol)
                        },
                    )+
                })
            }
        }
    };
}

#[cfg(target_os = "linux")]
pub(crate) use dynlib;

#[cfg(test)]
mod tests {
    use core::ffi::c_int;
    use std::cell::RefCell;
    use std::error::Error;

    use super::*;

    extern "C" fn add(a: c_int, b: c_int) -> c_int {
        a + b
    }

    extern "C" fn negate(value: c_int) -> c_int {
        -value
    }

    extern "C" fn answer() -> c_int {
        42
    }

    extern "C" fn store(target: *mut c_int, value: c_int) {
        // SAFETY: the tests pass a pointer to a live `c_int` of their own.
        unsafe { *target = value };
    }

    dynlib! {
        /// The table the tests load.
        struct Arithmetic: extern "C" {
            /// Two parameters and a result.
            fn add(a: c_int, b: c_int) -> c_int;
            /// One parameter.
            fn negate(value: c_int) -> c_int;
            /// No parameters.
            fn answer() -> c_int;
            /// No result, and a trailing comma.
            fn store(target: *mut c_int, value: c_int,);
        }
    }

    /// Every function of [`Arithmetic`], by name.
    fn all() -> Vec<(&'static str, *const c_void)> {
        vec![
            ("add", add as *const c_void),
            ("negate", negate as *const c_void),
            ("answer", answer as *const c_void),
            ("store", store as *const c_void),
        ]
    }

    /// A library that has the given symbols and records what it is asked
    /// for.
    struct Fake {
        symbols: Vec<(&'static str, *const c_void)>,
        asked: RefCell<Vec<Vec<u8>>>,
    }

    impl Fake {
        fn with(symbols: Vec<(&'static str, *const c_void)>) -> Self {
            Self {
                symbols,
                asked: RefCell::new(Vec::new()),
            }
        }

        fn without(names: &[&str]) -> Self {
            let mut symbols = all();
            symbols.retain(|(name, _)| !names.contains(name));
            Self::with(symbols)
        }
    }

    impl Library for Fake {
        fn symbol(&self, name: &CStr) -> *const c_void {
            self.asked
                .borrow_mut()
                .push(name.to_bytes_with_nul().to_vec());
            self.symbols
                .iter()
                .find(|(known, _)| known.as_bytes() == name.to_bytes())
                .map_or(core::ptr::null(), |&(_, address)| address)
        }
    }

    fn load(library: &Fake) -> Result<Arithmetic, MissingSymbols> {
        // SAFETY: every symbol the fake library has is the function of that
        // name above, which has the type the table declares. Functions of
        // this program are never unloaded.
        unsafe { Arithmetic::load(library) }
    }

    fn missing(library: &Fake) -> Vec<&'static str> {
        match load(library) {
            Ok(_) => panic!("the table loaded"),
            Err(error) => error.names,
        }
    }

    #[test]
    fn a_complete_library_loads_and_each_field_is_its_own_function() {
        // The library lists the symbols in another order than the table.
        let mut symbols = all();
        symbols.reverse();
        let table = load(&Fake::with(symbols)).unwrap_or_else(|error| panic!("{error}"));

        // SAFETY: `add` takes two integers and has no other requirement.
        assert_eq!(unsafe { (table.add)(2, 3) }, 5);
        // SAFETY: `negate` takes an integer and has no other requirement.
        assert_eq!(unsafe { (table.negate)(4) }, -4);
        // SAFETY: `answer` has no requirements.
        assert_eq!(unsafe { (table.answer)() }, 42);
        let mut target = 0;
        // SAFETY: `target` is a live `c_int` that nothing else borrows.
        unsafe { (table.store)(&raw mut target, 7) };
        assert_eq!(target, 7);
    }

    #[test]
    fn every_missing_symbol_is_reported_by_name() {
        assert_eq!(
            missing(&Fake::without(&["add", "answer", "store"])),
            ["add", "answer", "store"]
        );
        assert_eq!(
            missing(&Fake::with(Vec::new())),
            ["add", "negate", "answer", "store"]
        );
    }

    #[test]
    fn one_missing_symbol_is_reported_wherever_it_is_in_the_table() {
        for name in ["add", "negate", "answer", "store"] {
            assert_eq!(missing(&Fake::without(&[name])), [name]);
        }
    }

    #[test]
    fn missing_symbols_are_listed_in_table_order() {
        let mut symbols = all();
        symbols.retain(|(name, _)| *name == "answer");
        assert_eq!(missing(&Fake::with(symbols)), ["add", "negate", "store"]);
    }

    #[test]
    fn each_name_is_asked_for_once_as_a_c_string() {
        let complete = Fake::with(all());
        assert!(load(&complete).is_ok());
        let expected: [&[u8]; 4] = [b"add\0", b"negate\0", b"answer\0", b"store\0"];
        assert_eq!(*complete.asked.borrow(), expected);

        // A missing symbol does not end the search early.
        let empty = Fake::with(Vec::new());
        assert!(load(&empty).is_err());
        assert_eq!(*empty.asked.borrow(), expected);
    }

    #[test]
    fn the_message_names_every_missing_symbol() {
        let one = MissingSymbols {
            names: vec!["XOpenDisplay"],
        };
        assert_eq!(one.to_string(), "missing symbol: XOpenDisplay");
        let two = MissingSymbols {
            names: vec!["XOpenDisplay", "XPending"],
        };
        assert_eq!(two.to_string(), "missing symbols: XOpenDisplay, XPending");

        let from_load = load(&Fake::without(&["negate", "store"]))
            .err()
            .map(|error| error.to_string());
        assert_eq!(from_load.as_deref(), Some("missing symbols: negate, store"));
    }

    #[test]
    fn missing_symbols_is_an_error() {
        let error: Box<dyn Error> = Box::new(MissingSymbols { names: vec!["add"] });
        assert!(error.source().is_none());
    }
}
